using Microsoft.EntityFrameworkCore;
using System.Text.Json;
using System.Security.Cryptography;
using System.Text;
using System.Net;
using System.Text.RegularExpressions;
namespace Society.Api;

public class CommunityService(AppDb db,Access access) {
 public static readonly string[] Permissions=["activities.read","activities.official","activities.broadcast","activities.approve","activities.moderate","activities.settings","activities.analytics","events.manage","events.approve","events.invite","events.checkin","events.analytics"];
 public static readonly string[] ActivityNames=["Chapter News","Community Service","Volunteer Activities","Meetings","Training","Workshops","Educational Programs","Networking Events","Celebrations","Member Achievements","Leadership Updates","Awards","Environmental Activities","Health Programs","Fundraising Updates","Society Announcements"];
 public static readonly string[] EventNames=["Chapter Meeting","Committee Meeting","Training Program","Workshop","Community Service","Networking Event","Guest Lecture","Annual Celebration","Awards Ceremony","Regional Conference","District Convention","Society Annual General Meeting","National Convention","International Conference","Custom Event"];
 public static string[] TemplatePermissions(string name) => name.Contains("Treasurer") ? ["activities.read"] : name.Contains("President")||name.Contains("Secretary")||name.Contains("Coordinator")||name.Contains("Governor")||name.Contains("Manager") ? Permissions.Where(p=>p!="activities.settings").ToArray() : ["activities.read"];
 public static async Task Seed(AppDb db,Guid tenant) { db.Set<CommunityPolicy>().Add(new(){TenantId=tenant}); foreach(var name in ActivityNames)db.Set<ActivityCategory>().Add(new(){TenantId=tenant,Name=name});foreach(var name in EventNames)db.Set<ActivityCategory>().Add(new(){TenantId=tenant,Name=name,Kind="Event"});await Task.CompletedTask; }
 public static bool CommunicationAllowed(string json)=>MembershipService.Json(json)["communication"] is System.Text.Json.Nodes.JsonValue v&&v.TryGetValue<bool>(out var allowed)&&allowed;
 public static string Hash(string token)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(token)));
 public static string Token()=>Convert.ToHexString(RandomNumberGenerator.GetBytes(32));
 // Rich text is an allowlist of formatting-only tags. Attributes, links and embedded content are discarded.
 public static string Rich(string value) { if(value.Length>20000||value.Contains('\0'))throw new DomainException("Content exceeds the limit");var encoded=WebUtility.HtmlEncode(value);return Regex.Replace(encoded,@"&lt;(/?)(p|br|strong|b|em|i|u|ul|ol|li|blockquote|h3)&gt;",m=>"<"+m.Groups[1].Value+m.Groups[2].Value+">",RegexOptions.IgnoreCase); }
 public IQueryable<Membership> Mine(Guid tenant) {var now=DateTimeOffset.UtcNow;return db.Memberships.Where(m=>m.TenantId==tenant&&m.Status=="Active"&&m.EffectiveFrom<=now&&(m.EndsAt==null||m.EndsAt>now)&&db.Persons.Any(p=>p.Id==m.PersonId&&p.UserId==access.UserId));}
 public Task<CommunityPolicy> Policy(Guid tenant)=>db.Set<CommunityPolicy>().AsNoTracking().SingleAsync(p=>p.TenantId==tenant);
 public async Task<bool> Manage(Guid tenant,Guid? unit,string permission)=>await access.Can(tenant,permission,unit);
 public async Task<Guid[]> Audience(Guid tenant,Guid? unit,string visibility,Guid[]? selected,bool official,string permission="activities.broadcast") {
  await access.Member(tenant);var policy=await Policy(tenant);if(unit!=null&&!await db.Units.AnyAsync(u=>u.TenantId==tenant&&u.Id==unit&&u.Status=="Active"))throw new DomainException("Choose an active organization");
  if(official)await access.Require(tenant,permission=="events.manage"?"events.manage":"activities.official",unit);else if(!policy.MemberPosting||unit==null||!await Mine(tenant).AnyAsync(m=>m.ChapterId==unit))throw new AccessDeniedException();
  if(visibility=="Public"){if(!policy.PublicAllowed)throw new AccessDeniedException();await access.Require(tenant,permission,unit);return [];}
  if(visibility=="Chapter"){if(unit==null)throw new DomainException("Choose an organization");return [unit.Value];}
  if(!new[]{"Selected Chapters","Region","District","Society","International"}.Contains(visibility))throw new DomainException("Unknown visibility");
  await access.Require(tenant,permission,unit);if(visibility is "Society" or "International"){await access.Require(tenant,permission);return [];}
  if(visibility=="Selected Chapters"){var ids=(selected??[]).Distinct().ToArray();if(ids.Length is <1 or >500||await access.Visible(tenant,permission).CountAsync(u=>ids.Contains(u.Id))!=ids.Length)throw new AccessDeniedException();return ids;}
  if(unit==null)throw new DomainException("Choose a region or district");return await access.InWorkspace(access.Visible(tenant,permission),tenant,unit).Select(u=>u.Id).ToArrayAsync();
 }
 public IQueryable<Assignment> Global(Guid tenant,string permission){var now=DateTimeOffset.UtcNow;return db.Assignments.Where(ass=>ass.TenantId==tenant&&ass.UserId==access.UserId&&ass.UnitId==null&&ass.RevokedAt==null&&ass.StartsAt<=now&&(ass.EndsAt==null||ass.EndsAt>now)&&(ass.MembershipId==null||db.Memberships.Any(m=>m.Id==ass.MembershipId&&m.Status=="Active"&&m.EffectiveFrom<=now&&(m.EndsAt==null||m.EndsAt>now)))&&db.GovernanceRoles.Any(r=>r.Id==ass.RoleId&&r.Permissions.Contains(permission)));}
 public IQueryable<ActivityPost> Posts(Guid tenant,bool includeOwn=true) {
  var global=Global(tenant,"activities.read");var mine=Mine(tenant).Select(m=>m.ChapterId);var scopes=access.Visible(tenant,"activities.read").Select(u=>u.Id);var review=access.Visible(tenant,"activities.approve").Select(u=>u.Id);var globalModerate=Global(tenant,"activities.moderate");var moderate=access.Visible(tenant,"activities.moderate").Select(u=>u.Id);var globalReview=Global(tenant,"activities.approve");var blocked=db.Set<CommunityBlock>().Where(b=>b.TenantId==tenant&&(b.UserId==access.UserId||b.BlockedUserId==access.UserId));
  return db.Set<ActivityPost>().AsNoTracking().Where(p=>p.TenantId==tenant&&((includeOwn&&p.AuthorId==access.UserId)||(p.Status=="Published"&&(global.Any()||p.Visibility=="Public"||((p.Visibility=="Society"||p.Visibility=="International")&&mine.Any())||p.Audience.Any(id=>mine.Contains(id))||(p.UnitId!=null&&scopes.Contains(p.UnitId.Value))))||globalReview.Any()||globalModerate.Any()||(p.UnitId!=null&&(review.Contains(p.UnitId.Value)||moderate.Contains(p.UnitId.Value))))&&(globalModerate.Any()||(p.UnitId!=null&&moderate.Contains(p.UnitId.Value))||!blocked.Any(b=>b.UserId==p.AuthorId||b.BlockedUserId==p.AuthorId)));
 }
 public async Task<ActivityPost> Post(Guid tenant,Guid id){await access.Member(tenant);return await Posts(tenant).SingleOrDefaultAsync(p=>p.Id==id)??throw new AccessDeniedException();}
 public IQueryable<CommunityEvent> Events(Guid tenant) {var global=Global(tenant,"activities.read");var mine=Mine(tenant).Select(m=>m.ChapterId);var scopes=access.Visible(tenant,"activities.read").Select(u=>u.Id);var globalManage=Global(tenant,"events.manage");var manage=access.Visible(tenant,"events.manage").Select(u=>u.Id);return db.Set<CommunityEvent>().AsNoTracking().Where(e=>e.TenantId==tenant&&(e.AuthorId==access.UserId||globalManage.Any()||(e.UnitId!=null&&manage.Contains(e.UnitId.Value))||((e.Status=="Published"||e.Status=="Cancelled")&&(global.Any()||db.Set<EventInvitation>().Any(i=>i.TenantId==tenant&&i.EventId==e.Id&&i.UserId==access.UserId&&i.Status!="Revoked"&&i.ExpiresAt>DateTimeOffset.UtcNow)||e.Visibility=="Public"||((e.Visibility=="Society"||e.Visibility=="International")&&mine.Any())||e.Audience.Any(id=>mine.Contains(id))||(e.UnitId!=null&&scopes.Contains(e.UnitId.Value))))));}
 public async Task<CommunityEvent> Event(Guid tenant,Guid id){await access.Member(tenant);return await Events(tenant).SingleOrDefaultAsync(e=>e.Id==id)??throw new AccessDeniedException();}
 public IQueryable<Membership> Eligible(CommunityEvent e){var now=DateTimeOffset.UtcNow;var q=db.Memberships.Where(m=>m.TenantId==e.TenantId&&m.Status=="Active"&&m.EffectiveFrom<=now&&(m.EndsAt==null||m.EndsAt>now)&&(e.Audience.Length==0||e.Audience.Contains(m.ChapterId))&&(e.MemberIds.Length==0||e.MemberIds.Contains(m.Id))&&(e.CategoryIds.Length==0||e.CategoryIds.Contains(m.CategoryId)));if(e.CommitteeIds.Length>0)q=q.Where(m=>db.CommitteeMemberships.Any(c=>c.TenantId==e.TenantId&&e.CommitteeIds.Contains(c.CommitteeId)&&c.MembershipId==m.Id&&c.StartsAt<=now&&(c.EndsAt==null||c.EndsAt>now)));if(e.LeadersOnly)q=q.Where(m=>db.OfficerAppointments.Any(ap=>ap.TenantId==e.TenantId&&ap.MembershipId==m.Id&&ap.Status=="Approved"&&ap.StartsAt<=now&&ap.EndsAt>now));return q;}
 public async Task<Membership?> Eligibility(CommunityEvent e,Guid user,string? token=null){var member=await Eligible(e).Where(m=>db.Persons.Any(p=>p.Id==m.PersonId&&p.UserId==user)).OrderBy(m=>m.Id).FirstOrDefaultAsync();var email=await db.Users.Where(u=>u.Id==user).Select(u=>u.Email).SingleAsync();var hash=token==null?"":Hash(token);var invited=await db.Set<EventInvitation>().AnyAsync(i=>i.TenantId==e.TenantId&&i.EventId==e.Id&&i.Email==email&&i.ExpiresAt>DateTimeOffset.UtcNow&&i.Status!="Revoked"&&(i.UserId==user||i.TokenHash==hash));if(e.InvitationOnly&&!invited)throw new DomainException("A current invitation is required");if(member==null&&!(e.AllowGuests&&invited))throw new AccessDeniedException();return member;}
 public static string[] Stages(string json){try{var a=JsonSerializer.Deserialize<string[]>(json)??[];if(a.Length>5||a.Any(x=>!Permissions.Contains(x)))throw new Exception();return a;}catch{throw new DomainException("Approval stages must be a list of up to five community permissions");}}
 public async Task Decision(Guid tenant,Guid id,Guid author,Guid? unit,string kind,string stages,int stage,CommunityReview r){if(author==access.UserId)throw new AccessDeniedException();if(await db.Set<CommunityDecision>().AnyAsync(d=>d.TenantId==tenant&&d.ResourceId==id&&d.Kind==kind&&d.ActorId==access.UserId&&d.Decision=="Approve"&&d.Revision>=r.Revision-stage))throw new DomainException("Each approval stage requires an independent reviewer");var permissions=Stages(stages);if(stage>=permissions.Length)throw new DomainException("No approval stage remains");var permission=permissions[stage];await access.Require(tenant,permission,unit);if(!new[]{"Approve","Reject","Changes Requested"}.Contains(r.Decision)||r.Note.Length>2000)throw new DomainException("Invalid review decision");var now=DateTimeOffset.UtcNow;var roles=await (from ass in db.Assignments join role in db.GovernanceRoles on ass.RoleId equals role.Id where ass.TenantId==tenant&&ass.UserId==access.UserId&&ass.RevokedAt==null&&ass.StartsAt<=now&&(ass.EndsAt==null||ass.EndsAt>now)&&role.Permissions.Contains(permission) select role.Name).ToArrayAsync();db.Set<CommunityDecision>().Add(new(){TenantId=tenant,ResourceId=id,ActorId=access.UserId,UnitId=unit,Kind=kind,Decision=r.Decision,Permission=permission,Roles=JsonSerializer.Serialize(roles),Note=r.Note,Revision=r.Revision});access.Audit(tenant,kind.ToLower()+".review."+r.Decision,id);}
 public void Version(Guid tenant,Guid id,string kind,int revision,object snapshot){db.Set<CommunityVersion>().Add(new(){TenantId=tenant,ResourceId=id,ActorId=access.UserId,Kind=kind,Revision=revision,Snapshot=JsonSerializer.Serialize(snapshot)});access.Audit(tenant,kind.ToLower()+".saved",id);}
 public static string Ready(DateTimeOffset? scheduled)=>scheduled>DateTimeOffset.UtcNow?"Scheduled":"Published";
 public static void EventDates(EventWrite r){if(r.EndsAt<=r.StartsAt||r.RegistrationCloses>r.EndsAt||r.RegistrationOpens>=r.RegistrationCloses||r.Capacity is <1 or >100000||r.MaxCompanions is <0 or >10||r.Venue.Length>500||!new[]{"In Person","Online","Hybrid"}.Contains(r.Mode))throw new DomainException("Check event dates, capacity and venue");try{TimeZoneInfo.FindSystemTimeZoneById(r.TimeZone);}catch{throw new DomainException("Use a valid IANA time zone");}if(r.OnlineUrl!=null&&r.OnlineUrl!=""&&(!Uri.TryCreate(r.OnlineUrl,UriKind.Absolute,out var u)||u.Scheme!="https"))throw new DomainException("Online venue must use HTTPS");}
 public async Task Promote(CommunityEvent e){var occupied=await db.Set<EventRegistration>().Where(r=>r.TenantId==e.TenantId&&r.EventId==e.Id&&r.Status=="Confirmed").SumAsync(r=>r.Companions+1);var queued=await db.Set<EventRegistration>().Where(r=>r.TenantId==e.TenantId&&r.EventId==e.Id&&r.Status=="Waitlisted").OrderBy(r=>r.At).ThenBy(r=>r.Id).Take(100).ToListAsync();foreach(var r in queued){if(occupied+r.Companions+1>e.Capacity)break;try{await Eligibility(e,r.UserId);}catch{continue;}r.Status="Confirmed";r.Revision++;occupied+=r.Companions+1;access.Audit(e.TenantId,"event.waitlist.promoted",r.Id);}}
}

public class CommunityPublisher(IServiceScopeFactory factory,ILogger<CommunityPublisher> log):BackgroundService {
 static async Task<bool> CurrentAuthority(AppDb db,Guid tenant,Guid author,Guid? unit,bool official,bool isEvent,string visibility){var now=DateTimeOffset.UtcNow;if(!await db.Tenants.AnyAsync(t=>t.Id==tenant&&t.Status=="Active")||!await db.Links.AnyAsync(l=>l.TenantId==tenant&&l.UserId==author))return false;if(unit!=null&&!await db.Units.AnyAsync(u=>u.TenantId==tenant&&u.Id==unit&&u.Status=="Active"))return false;var policy=await db.Set<CommunityPolicy>().SingleAsync(p=>p.TenantId==tenant);if(visibility=="Public"&&!policy.PublicAllowed)return false;if(!official)return policy.MemberPosting&&await db.Memberships.AnyAsync(m=>m.TenantId==tenant&&m.ChapterId==unit&&m.Status=="Active"&&m.EffectiveFrom<=now&&(m.EndsAt==null||m.EndsAt>now)&&db.Persons.Any(p=>p.Id==m.PersonId&&p.UserId==author));var permission=isEvent?"events.manage":"activities.official";if(unit!=null)return await Access.UnitsFor(db,tenant,author,permission).AnyAsync(u=>u.Id==unit);return await db.Assignments.AnyAsync(ass=>ass.TenantId==tenant&&ass.UserId==author&&ass.UnitId==null&&ass.RevokedAt==null&&ass.StartsAt<=now&&(ass.EndsAt==null||ass.EndsAt>now)&&(ass.MembershipId==null||db.Memberships.Any(m=>m.Id==ass.MembershipId&&m.Status=="Active"&&m.EffectiveFrom<=now&&(m.EndsAt==null||m.EndsAt>now)))&&db.GovernanceRoles.Any(r=>r.Id==ass.RoleId&&r.Permissions.Contains(permission)));}
 protected override async Task ExecuteAsync(CancellationToken stop){while(!stop.IsCancellationRequested){try{using var scope=factory.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDb>();var now=DateTimeOffset.UtcNow;await using var tx=await db.Database.BeginTransactionAsync(stop);var posts=await db.Set<ActivityPost>().FromSqlInterpolated($"SELECT * FROM \"ActivityPost\" WHERE \"Status\"='Scheduled' AND \"ScheduledAt\"<={now} ORDER BY \"ScheduledAt\" LIMIT 50 FOR UPDATE SKIP LOCKED").ToListAsync(stop);foreach(var p in posts){var permitted=await CurrentAuthority(db,p.TenantId,p.AuthorId,p.UnitId,p.Official,false,p.Visibility);p.Status=permitted?"Published":"Changes Requested";p.PublishedAt=permitted?now:null;p.Revision++;db.Audits.Add(new(){TenantId=p.TenantId,ActorId=p.AuthorId,Action="post.scheduled."+p.Status,ResourceId=p.Id});}var events=await db.Set<CommunityEvent>().FromSqlInterpolated($"SELECT * FROM \"CommunityEvent\" WHERE \"Status\"='Scheduled' AND \"ScheduledAt\"<={now} ORDER BY \"ScheduledAt\" LIMIT 50 FOR UPDATE SKIP LOCKED").ToListAsync(stop);foreach(var e in events){var permitted=await CurrentAuthority(db,e.TenantId,e.AuthorId,e.UnitId,true,true,e.Visibility);e.Status=permitted?"Published":"Changes Requested";e.PublishedAt=permitted?now:null;e.Revision++;db.Audits.Add(new(){TenantId=e.TenantId,ActorId=e.AuthorId,Action="event.scheduled."+e.Status,ResourceId=e.Id});}await db.SaveChangesAsync(stop);await tx.CommitAsync(stop);}catch(Exception e)when(!stop.IsCancellationRequested){log.LogError(e,"Community publication failed");}try{await Task.Delay(1000,stop);}catch(OperationCanceledException){break;}}}
}
